from itertools import cycle

def decrypt_vigenere(ciphertext, key):
    plaintext = ""
    key_cycle = cycle(key)
    for c in ciphertext:
        if c.isalpha():
            shift = ord(next(key_cycle)) - ord('a')
            decrypted_char = chr(((ord(c) - ord('a') - shift) % 26) + ord('a'))
            plaintext += decrypted_char
        else:
            plaintext += c
    return plaintext

